SELECT CASE WHEN r.region_id = 1 THEN 'Dhaka' ELSE 'Other divisions' END, COUNT(*) FILTER (WHERE p.method = 'cod') * 1.0 / COUNT(*) FROM payments p JOIN orders o USING (order_id) JOIN customer_addresses a USING (address_id) JOIN cities c ON c.city_id = a.city_id JOIN regions r ON r.region_id = c.region_id WHERE p.status = 'captured' AND o.is_deleted = FALSE AND o.order_at >= TIMESTAMP '2024-01-01 00:00:00' AND o.order_at < TIMESTAMP '2025-01-01 00:00:00' GROUP BY 1
